import * as THREE from 'three/webgpu';
import { color, vec3, positionLocal, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  if (config.scenePosition) root.position.copy(config.scenePosition);
  if (config.sceneRotation) root.rotation.copy(config.sceneRotation);
  if (config.sceneScale) root.scale.copy(config.sceneScale);

  const CARD_W = 1.5, CARD_H = 1.9, GAP = 0.25, TOTAL_W = 5.0;
  const PAD = 0.375, ICON_D = 0.4, ICON_EXT = 0.05;
  const startX = -TOTAL_W / 2 + CARD_W / 2;
  const xPos = [0, 1, 2].map(i => startX + i * (CARD_W + GAP));

  const cardsData = [
    { icon: "01", title: "In-House Calibre", body: "Every movement is designed, machined, and finished under one roof." },
    { icon: "02", title: "Five-Year Guarantee", body: "Each piece is serviced free of charge for five years from delivery." },
    { icon: "03", title: "Hand-Finished Dials", body: "Guilloche cut on a 1912 rose engine, one dial at a time." }
  ];

  const tlStagger = gsap.timeline();

  cardsData.forEach((data, idx) => {
    const card = new THREE.Group();
    card.position.set(xPos[idx], 0.2, 0);
    root.add(card);

    const meshesToAnimate = [];

    // Card background
    const bgGeom = new THREE.PlaneGeometry(CARD_W, CARD_H);
    const bgMat = new THREE.MeshStandardNodeMaterial({
      colorNode: mix(
        vec3(color('#191921')),
        vec3(color('#121218')),
        positionLocal.y.remap(CARD_H / 2, -CARD_H / 2, 0, 1)
      ),
      roughness: 0.6,
      metalness: 0.25,
      clearcoat: 0.15,
      transparent: true,
      opacity: 0
    });
    const bgMesh = new THREE.Mesh(bgGeom, bgMat);
    card.add(bgMesh);
    meshesToAnimate.push(bgMesh);

    // Icon seat (disc)
    const seatGeom = new THREE.CylinderGeometry(ICON_D / 2, ICON_D / 2, ICON_EXT, 32);
    const seatMat = new THREE.MeshStandardNodeMaterial({
      color: '#1a1a20',
      roughness: 0.55,
      metalness: 0.5,
      clearcoat: 0.2,
      transparent: true,
      opacity: 0,
      emissive: '#000000',
      emissiveIntensity: 1.6
    });
    const seatMesh = new THREE.Mesh(seatGeom, seatMat);
    const seatY = CARD_H / 2 - PAD - ICON_D / 2;
    seatMesh.position.set(0, seatY, 0.05);
    card.add(seatMesh);
    meshesToAnimate.push(seatMesh);
    card.userData.seatMat = seatMat;

    // Icon glyph text
    let iconText;
    try {
      iconText = ctx.fontAtlas.createText(data.icon, {
        fontSize: 20,
        fontWeight: 700,
        fontFamily: 'JetBrains Mono',
        color: '#ff2a38',
        emissive: '#ff2a38',
        emissiveIntensity: 1.6,
        transparent: true,
        opacity: 0
      });
    } catch (e) {
      const g = new THREE.PlaneGeometry(0.2, 0.2);
      const m = new THREE.MeshBasicMaterial({ color: '#ff2a38', transparent: true, opacity: 0 });
      iconText = new THREE.Mesh(g, m);
    }
    iconText.position.set(0, seatY, 0.15);
    card.add(iconText);
    meshesToAnimate.push(iconText);

    // Title text
    const titleY = seatY - ICON_D / 2 - 0.25;
    let titleText;
    try {
      titleText = ctx.fontAtlas.createText(data.title, {
        fontSize: 20,
        fontWeight: 600,
        fontFamily: 'Lora',
        color: '#e8ecf2',
        maxWidth: CARD_W - 2 * PAD,
        align: 'center',
        transparent: true,
        opacity: 0
      });
    } catch (e) {
      const g = new THREE.PlaneGeometry(CARD_W - 2 * PAD, 0.3);
      const m = new THREE.MeshBasicMaterial({ color: '#e8ecf2', transparent: true, opacity: 0 });
      titleText = new THREE.Mesh(g, m);
    }
    titleText.position.set(0, titleY, 0.1);
    card.add(titleText);
    meshesToAnimate.push(titleText);

    // Body text
    const bodyY = titleY - 0.3 - 0.125;
    let bodyText;
    try {
      bodyText = ctx.fontAtlas.createText(data.body, {
        fontSize: 13,
        fontWeight: 400,
        fontFamily: 'JetBrains Mono',
        color: '#b8bcc4',
        maxWidth: CARD_W - 2 * PAD,
        align: 'center',
        transparent: true,
        opacity: 0
      });
    } catch (e) {
      const g = new THREE.PlaneGeometry(CARD_W - 2 * PAD, 0.5);
      const m = new THREE.MeshBasicMaterial({ color: '#b8bcc4', transparent: true, opacity: 0 });
      bodyText = new THREE.Mesh(g, m);
    }
    bodyText.position.set(0, bodyY, 0.1);
    card.add(bodyText);
    meshesToAnimate.push(bodyText);

    // Stagger animation: fade-up
    const delay = idx * 0.08;
    tlStagger.to(card.position, { y: 0, duration: 0.5, ease: "cubic-bezier(0.25,0.46,0.45,0.94)" }, delay);
    meshesToAnimate.forEach(mesh => {
      tlStagger.to(mesh.material, { opacity: 1, duration: 0.5, ease: "cubic-bezier(0.25,0.46,0.45,0.94)" }, delay);
    });

    // Hover handlers
    card.userData.handlers = {
      mouseenter: () => {
        gsap.to(card.position, {
          y: 0.06,
          z: 0.12,
          duration: 0.18,
          ease: "cubic-bezier(0.25,0.46,0.45,0.94)",
          overwrite: 'auto'
        });
        gsap.to(seatMat, {
          emissiveIntensity: 2.2,
          duration: 0.18
        });
      },
      mouseleave: () => {
        gsap.to(card.position, {
          y: 0,
          z: 0,
          duration: 0.18,
          ease: "cubic-bezier(0.25,0.46,0.45,0.94)",
          overwrite: 'auto'
        });
        gsap.to(seatMat, {
          emissiveIntensity: 1.6,
          duration: 0.18
        });
      }
    };
  });

  root.userData.cleanup = () => {
    tlStagger.kill();
    root.traverse(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) obj.material.forEach(m => m.dispose());
        else obj.material.dispose();
      }
    });
  };

  return root;
}
